// Optional local signing for `assembleRelease`. The keystore is generated by
// scripts/build-android.sh into apps/android/keystore (git-ignored). Real release signing keys
// are out of scope for this repository.
val localKeystore = rootProject.file("keystore/local-release.jks")

android {
    namespace = "app.woodwardtunnel"
    compileSdk = 36

    defaultConfig {
        applicationId = "app.woodwardtunnel"
        minSdk = 24
        targetSdk = 35
        versionCode = 1
        versionName = "0.1.0"
        androidResources.localeFilters += listOf("fa", "en")
        ndk { abiFilters += listOf("arm64-v8a", "armeabi-v7a", "x86_64", "x86") }
    }

    signingConfigs {
        if (localKeystore.exists()) {
            create("local") {
                storeFile = localKeystore
                storePassword = "woodward-local"
                keyAlias = "local"
                keyPassword = "woodward-local"
            }
        }
    }

    buildTypes {
        release {
            isMinifyEnabled = true
            isShrinkResources = true
            proguardFiles(getDefaultProguardFile("proguard-android-optimize.txt"), "proguard-rules.pro")
            signingConfigs.findByName("local")?.let { signingConfig = it }
        }
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
        isCoreLibraryDesugaringEnabled = false
    }

    buildFeatures {
        compose = true
        buildConfig = true
    }

    sourceSets {
        // Kotlin bindings generated from libwtcore.so by scripts/build-android.sh.
        getByName("main").java.srcDir("src/generated/kotlin")
    }

    packaging {
        jniLibs {
            // gomobile libraries are happier when extracted; the APK stays debuggable either way.
            useLegacyPackaging = true
        }
        resources.excludes += setOf("/META-INF/{AL2.0,LGPL2.1}", "DebugProbesKt.bin")
    }

    lint {
        abortOnError = false
    }
}

kotlin {
