tasks.register("checkNativeInputs") {
    description = "Fails early with a clear message when build-android.sh has not produced the native inputs."
    doLast {
        val missing = listOf(
            "libs/libbox.aar",
            "src/generated/kotlin/uniffi/wtcore/wtcore.kt",
            "src/main/jniLibs/arm64-v8a/libwtcore.so",
        ).filter { !File(projectDir, it).exists() }
        if (missing.isNotEmpty()) {
            throw GradleException("Missing $missing. Run scripts/build-android.sh first.")
        }
    }
}
tasks.matching { it.name == "preBuild" }.configureEach { dependsOn("checkNativeInputs") }
